function hash(s){let h=2166136261;for(const ch of T(s)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
function validDate(v){const t=T(v);if(!/^\d{4}-\d{2}-\d{2}$/.test(t))return '';const d=new Date(t+'T00:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===t&&d<=new Date()?t:'';}
function evidenceDate(quote,date){const t=norm(quote),d=new Date(date+'T00:00:00Z'),day=d.getUTCDate(),month=d.getUTCMonth()+1,year=d.getUTCFullYear();if(t.includes(date))return true;for(const m of t.matchAll(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})\b/g))if(+m[1]===day&&+m[2]===month&&+m[3]===year)return true;const months=[['january','يناير'],['february','فبراير'],['march','مارس'],['april','ابريل'],['may','مايو'],['june','يونيو'],['july','يوليو'],['august','اغسطس'],['september','سبتمبر'],['october','اكتوبر'],['november','نوفمبر'],['december','ديسمبر']];return months[month-1].some(x=>new RegExp('(?:'+day+'\\s+'+x+'[ ,]+.*?'+year+'|'+x+'\\s+'+day+'[ ,]+.*?'+year+')','i').test(t));}
function realPost(url){try{const u=new URL(url);return /\/posts\/|\/reel[s]?\/|\/videos\/|\/p\/|\/shorts\/|\/watch|\/video\/|\/status\//i.test(u.pathname)||u.searchParams.has('v')||u.searchParams.has('story_fbid');}catch{return false;}}
function acceptExtract(c,s,r){const fp=hash(s.text),oldByKey=new Map(c.facts.filter(f=>f.sourceId===s.id).map(f=>[f.field+'|'+norm(f.value),f]));c.facts=c.facts.filter(f=>f.sourceId!==s.id);c.findings=c.findings.filter(f=>f.sourceId!==s.id);c.posts=c.posts.filter(p=>p.sourceId!==s.id);for(const f of A(r.facts)){if(!FIELDS[f.field]||!T(f.value).trim())continue;let ev=validEvidence(f.evidence,c,[s]);if(!ev.length){limit(c,'معلومة مرفوضة لغياب اقتباس مطابق: '+(FIELDS[f.field]||f.field)+' — '+s.platform);continue;}if(s.kind!=='client'&&['customer','geo','goal','baseline','focusService','budget','problem'].includes(f.field)){limit(c,'لم نستنتج '+FIELDS[f.field]+' من مصدر عام؛ يحتاج تصريح العميل.');continue;}if(/(?:CPA|لكل نتيجة|تكلفة المحادثة)/i.test(T(f.value))&&!['description'].includes(f.field))continue;const prev=oldByKey.get(f.field+'|'+norm(f.value));c.facts.push({id:prev?.id||uid(),sourceId:s.id,field:f.field,value:T(f.value).slice(0,600),evidence:ev,origin:s.kind==='client'?'client':'source',status:prev?.status||'pending'});}
for(const f of A(r.findings).slice(0,8)){const ev=validEvidence(f.evidence,c,[s]);if(!T(f.title))continue;const type=ev.length&&['strength','issue'].includes(f.type)?f.type:'hypothesis';c.findings.push({id:uid(),sourceId:s.id,type,title:T(f.title).slice(0,180),observation:T(f.observation).slice(0,500),impact:T(f.impact).slice(0,300),proposal:T(f.proposal).slice(0,400),evidence:ev,status:'pending'});}
for(const p of A(r.posts)){const ev=validEvidence(p.evidence,c,[s]),url=publicURL(p.url),date=validDate(p.date);if(s.kind==='client'||!ev.length||!url||!realPost(url)||!date||!norm(s.text).includes(norm(p.text))||!s.text.includes(url)&&!A(s.links).some(x=>canonical(x)===canonical(url)))continue;const quoteText=ev.map(x=>x.quote).join(' ');if(!evidenceDate(quoteText,date))continue;c.posts.push({id:hash(url),sourceId:s.id,url,date,text:T(p.text).slice(0,1500),category:CATEGORIES.includes(p.category)?p.category:'أخرى',format:FORMATS.includes(p.format)?p.format:'غير محدد',evidence:ev,status:'pending'});}
const le=validEvidence(r.lastActivity?.evidence,c,[s]);s.lastActivity=le.length&&validDate(r.lastActivity?.date)?{date:r.lastActivity.date,evidence:le}:null;s.summary=T(r.summary).slice(0,350);s.extraction={fp,at:Date.now()};A(r.limits).slice(0,5).forEach(x=>limit(c,s.platform+': '+T(x)));touch(c);}
async function examine(){await withJob('فحص المنصات والموقع',async(c,signal,status)=>{const docs=c.sources.filter(s=>['read','partial'].includes(s.status)&&s.identity==='confirmed');if(!docs.length){limit(c,'تعذر فحص المنصات: مفيش مصدر مقروء ومؤكد الهوية. نكمل بمعلومات العميل والأسئلة، وليس بتشخيص مختلق.');c.examinedAt=Date.now();return;}for(let i=0;i<docs.length;i++){const s=docs[i];if(s.extraction?.fp===hash(s.text)&&!s.extractError)continue;status('فحص '+s.platform+' — '+(i+1)+' من '+docs.length);try{const r=await ai(`استخرج معلومات هذا المصدر فقط. ${s.kind==='client'?'هذه رسالة قدمها العميل؛ انسب أقواله إليه ولا تثبتها خارجيًا.':'هذه منصة عامة؛ لا تستخرج goal أو geo أو baseline أو focusService أو budget أو customer الفعلي منها.'} فحص المنصة: التعريف والخدمات والتميّز الموثق والثقة ووضوح التواصل والحجز. لا تثبت جودة طبية أو تشغيل التتبع أو سرعة الموقع من نص. اقتراحات عملية مرتبطة بالملاحظة وليست نصائح عامة. للمحتوى: استخرج آخر المنشورات المؤرخة المتاحة مهما كان تاريخها، وليس آخر 90 يوم؛ عينة أقصاها 30 منشورًا. التاريخ يجب أن يظهر في الدليل. الجمهور في المحتوى يوصف كمخاطَب لا كمشتري فعلي. ${EXTRACTION_SCHEMA}\nالمصدر id=${s.id} url=${s.url}\n${T(s.text).slice(0,30000)}`,{signal,max:5500});acceptExtract(c,s,r);delete s.extractError;}catch(e){if(signal.aborted)throw e;s.extractError=e.message;limit(c,'تعذر استخراج '+s.platform+' ('+s.url+'): '+e.message+'؛ باقي المصادر مستمرة.');touch(c);}}c.examinedAt=Date.now();});}
function factsFor(c,field){return c.facts.filter(f=>f.field===field&&f.status==='approved'&&c.sources.some(s=>s.id===f.sourceId&&s.identity==='confirmed')&&validEvidence(f.evidence,c).length);}
function known(c,field){const aliases={focusService:['focusService','offer'],baseline:['baseline','currentResults'],problem:['problem'],goal:['goal'],customer:['customer'],geo:['geo'],usp:['usp'],budget:['budget'],funnel:['funnel']};for(const k of aliases[field]||[field])if(T(c.answers[k]).trim()&&T(c.answers[k])!=='غير محدد')return {value:T(c.answers[k]),origin:'إجابة مسجلة'};const fs=factsFor(c,field);if(fs.length)return {value:[...new Set(fs.map(x=>x.value))].join('، '),origin:'معلومة معتمدة',evidence:fs.flatMap(x=>x.evidence)};return null;}
function computeConflicts(c){const old=new Map(c.conflicts.map(x=>[x.key,x]));const out=[];for(const field of ['addresses','prices','hours','specialty','contacts']){const fs=c.facts.filter(f=>f.field===field&&f.status==='approved');const pairs=[];for(let i=0;i<fs.length;i++)for(let j=i+1;j<fs.length;j++)if(fs[i].sourceId!==fs[j].sourceId&&norm(fs[i].value)!==norm(fs[j].value))pairs.push([fs[i],fs[j]]);if(!pairs.length)continue;const key=field+'|'+hash(fs.map(f=>f.value).sort().join('|'));out.push({id:old.get(key)?.id||uid(),key,field,type:'difference',title:'اختلاف يحتاج تفسيرًا: '+FIELDS[field],reason:'قد يكون تحديثًا أو فروعًا أو خدمات مختلفة؛ لا نحكم أنه خطأ قبل حسم السياق.',items:fs,status:old.get(key)?.status||'open',resolution:old.get(key)?.resolution||''});}c.conflicts=out;touch(c);return out;}
function sample(c){const groups={};const seen=new Set();for(const p of c.posts.filter(x=>x.status==='approved')){if(seen.has(canonical(p.url)))continue;seen.add(canonical(p.url));const s=c.sources.find(x=>x.id===p.sourceId);if(!s||s.identity!=='confirmed')continue;const name=s.platform;(groups[name]||=[]).push(p);}return Object.entries(groups).map(([name,arr])=>{const posts=arr.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30);const total=posts.length;return {name,posts,total,from:posts.at(-1)?.date,to:posts[0]?.date,mix:CATEGORIES.map(category=>({category,n:posts.filter(p=>p.category===category).length})).filter(x=>x.n).map(x=>({...x,pct:Math.round(x.n/total*1000)/10})),formats:FORMATS.map(format=>({format,n:posts.filter(p=>p.format===format).length})).filter(x=>x.n),daysSince:Math.max(0,Math.floor((Date.now()-new Date(posts[0].date).getTime())/86400000))};});}
async function contentReview(){await withJob('تقييم آخر عينة محتوى',async(c,signal,status)=>{const samples=sample(c);if(!samples.length){c.contentReview={summary:'مفيش عينة منشورات مؤرخة ومعتمدة كفاية لحساب النسب. ده تعذر قراءة، مش حكم إن الصفحة مفيهاش محتوى.',strengths:[],gaps:[],recommendations:[],missing:['رابط آخر منشورات أو صورها بالنص والتاريخ.']};return;}status('ربط توزيع المحتوى بنقاط القوة…');const r=await ai(`قيم هذه العينة فقط، لا تصف كل الصفحة. النسب محسوبة بالكود لا تعد حسابها. هل العينة تعكس تخصص الدكتور ونقاط قوته المعتمدة ومخاوف الجمهور وطريق الحجز؟ لا تستخدم نسبًا مثالية ثابتة. الهدف إن لم يوجد لا تحكم بملاءمة نهائية. الفراغ الزمني فرق بين النشاط الحالي وجودة المحتوى وقت النشر. لا ادعاء عن فيديو غير مشاهد. JSON {"summary":"","strengths":[{"text":"","postIds":[]}],"gaps":[{"text":"","postIds":[]}],"recommendations":[{"text":"","why":"","postIds":[]}],"missing":[]}. بيانات ${JSON.stringify({samples:samples.map(s=>({...s,posts:s.posts.map(p=>({id:p.id,text:p.text,date:p.date,category:p.category,format:p.format}))})),facts:c.facts.filter(x=>x.status==='approved'),goal:known(c,'goal')})}`,{signal,max:3500});const allowed=new Set(samples.flatMap(s=>s.posts.map(p=>p.id)));for(const k of ['strengths','gaps','recommendations'])r[k]=A(r[k]).filter(x=>A(x.postIds).some(id=>allowed.has(id))).map(x=>({...x,postIds:A(x.postIds).filter(id=>allowed.has(id))}));c.contentReview=r;c.contentAt=Date.now();});}
function researchContext(c){return {name:c.name,specialty:c.specialty,facts:c.facts.filter(f=>f.status==='approved'),findings:c.findings.filter(f=>f.status==='approved'),differences:c.conflicts.map(x=>({field:x.field,status:x.status,resolution:x.resolution})),content:c.contentReview,samples:sample(c).map(x=>({platform:x.name,total:x.total,from:x.from,to:x.to,mix:x.mix})),answers:c.answers,limits:c.limits,decisions:c.decisions};}
async function priorities(){await withJob('ترتيب فرص التحسين',async(c,signal,status)=>{status('اختيار أهم الملاحظات وربطها بالقرارات…');const r=await ai(`قدّم أهم 3 إلى 5 فرص تحسين للبحث المبدئي فقط، مرتبطة بملاحظات اعتمدها المستخدم. لا تكتب ميديا بلان. لكل مقترح rationale مختصر، وإيه محتاج رأي المستخدم قبل القرار. أرجع IDs للملاحظات الموجودة ولا تخترع. لو الأدلة قليلة اكتب أقل من 3 بدل الحشو. JSON {"summary":"","items":[{"title":"","findingIds":[],"action":"","why":"","decisionQuestion":"","dependency":""}],"limits":[]}. البيانات ${JSON.stringify(researchContext(c))}`,{signal,max:2800});const allowed=new Set(c.findings.filter(x=>x.status==='approved').map(x=>x.id));r.items=A(r.items).filter(x=>A(x.findingIds).some(id=>allowed.has(id))).slice(0,5).map(x=>({...x,id:uid(),status:'proposed',findingIds:A(x.findingIds).filter(id=>allowed.has(id))}));c.priorities=r;c.prioritiesAt=Date.now();});}
function missing(c){const qs=QUESTIONS.filter(([key])=>!known(c,key)).map(([field,text,why])=>({field,text,why}));const pending=c.facts.filter(f=>f.status==='pending'&&validEvidence(f.evidence,c).length);const conflictQuestions=c.conflicts.filter(x=>x.status==='ask').map(x=>({field:'conflict_'+x.id,text:'لحسم '+FIELDS[x.field]+': '+x.resolution,why:'تحديد المعلومة المعتمدة بدل الاختيار بصمت'}));return {questions:[...conflictQuestions,...qs.filter(q=>!pending.some(f=>f.field===q.field))],pending:qs.filter(q=>pending.some(f=>f.field===q.field))};}
function evidenceHTML(ev,c){return A(ev).map(e=>{const s=c.sources.find(x=>x.id===e.sourceId);let url=publicURL(e.url);try{if(url&&!realPost(url)){const u=new URL(url);u.hash=':~:text='+encodeURIComponent(e.quote.slice(0,220));url=u.href;}}catch{}return `<details class="evidence"><summary>الدليل · ${E(s?.platform||e.kind)}</summary><blockquote>${E(e.quote)}</blockquote>${url?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">افتح موضع الدليل ↗</a>`:'<small>نص أو صورة أضافها الفريق؛ ليس مصدر ويب مستقلًا.</small>'}</details>`;}).join('');}
function btn(label,onclick,cls='',disabled=false){return `<button class="${cls}" onclick="${onclick}" ${disabled?'disabled':''}>${label}</button>`;}
function empty(t){return `<div class="empty"><span>◎</span><p>${E(t)}</p></div>`;}
function sourceCards(c){return c.sources.map(s=>`<article class="card source-card"><div class="row"><b>${E(s.platform)}</b><span class="tag ${s.identity==='pending'?'amber':s.status==='unavailable'?'red':'blue'}">${s.identity==='rejected'?'مستبعد':s.identity==='pending'?'هوية تحتاج تأكيد':s.status==='read'?'مقروء':s.status==='partial'?'مقروء جزئيًا':s.status==='unavailable'?'تعذر الوصول':'لم يُقرأ بعد'}</span></div>${s.url?`<a class="url" href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.url)}</a>`:`<p>${E(s.title||'مواد أضافها الفريق')}</p>`}<p>${E(s.summary||s.note||s.reason)}</p>${s.lastActivity?`<small>آخر نشاط ظاهر: ${E(s.lastActivity.date)} — من المصدر المتاح</small>`:''}${s.identity==='pending'?`<p class="muted">الاسم والتخصص وحدهم مش كفاية. راجع الرقم أو العنوان أو الرابط الرسمي.</p><div class="actions">${btn('أكدت إنه نفس العميل',`identity('${s.id}','confirmed')`)}${btn('مش العميل',`identity('${s.id}','rejected')`,'ghost')}</div>`:''}${s.text?`<details><summary>النص المقروء للتشخيص</summary><pre>${E(s.text)}</pre></details>`:''}${s.identity==='confirmed'&&s.status==='unavailable'?btn('أعد قراءة المصدر',`retrySource('${s.id}')`,'ghost',!!job):''}</article>`).join('');}
function findingCards(c){return c.findings.filter(f=>f.status!=='rejected').map(f=>`<article class="card"><div class="row"><span class="tag ${f.type==='strength'?'green':f.type==='issue'?'amber':''}">${f.type==='strength'?'نقطة قوة':f.type==='issue'?'ملاحظة بالدليل':'فرضية للتحقق'}</span><small>${E(c.sources.find(s=>s.id===f.sourceId)?.platform)}</small></div><h3>${E(f.title)}</h3><p>${E(f.observation)}</p><div class="insight"><b>الأثر المحتمل</b><p>${E(f.impact)}</p><b>اقتراحي</b><p>${E(f.proposal)}</p></div>${evidenceHTML(f.evidence,c)}<div class="actions">${f.status==='approved'?'<span class="tag green">معتمدة</span>':btn('اعتمد الملاحظة',`review('findings','${f.id}','approved')`)}${btn('استبعد',`review('findings','${f.id}','rejected')`,'ghost')}</div></article>`).join('');}
function factsHTML(c){return `<details class="card" open><summary>المعلومات المستخرجة · ${c.facts.filter(f=>f.status==='pending').length} تحتاج مراجعة</summary>${c.facts.filter(f=>f.status!=='rejected').map(f=>`<div class="fact"><div><span class="muted">${E(FIELDS[f.field])} · ${f.origin==='client'?'تصريح العميل':'من مصدر مقروء'}</span><p>${E(f.value)}</p>${evidenceHTML(f.evidence,c)}</div><div>${f.status==='approved'?'<span class="tag green">معتمدة</span>':btn('اعتماد',`review('facts','${f.id}','approved')`)}${btn('استبعاد',`review('facts','${f.id}','rejected')`,'ghost')}</div></div>`).join('')||'<p>المعلومات هتظهر بعد فحص المصادر المقروءة.</p>'}</details>`;}
function discussion(c){const messages=A(c.discussions[step]);return `<section class="card discussion"><div class="row"><h2>نفكر فيها سوا</h2><span class="tag">مناقشة ${STEPS[step]}</span></div><p class="muted">ناقش الاقتراح، اطلب تفسير الدليل، أو حدّد اللي عايز نركز عليه. اعتماد القرار منفصل عن المحادثة.</p><div id="chatlog">${messages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><small>${m.role==='user'?'إنت':'مستشارك'}</small><p>${E(m.text)}</p>${m.evidence?evidenceHTML(m.evidence,c):''}</div>`).join('')}</div><form onsubmit="event.preventDefault();askDiscussion()"><label for="discuss">رأيك أو سؤالك</label><textarea id="discuss" rows="2"></textarea><div class="actions">${btn('ناقشني','askDiscussion()','',!!job)}${btn('سجّل قرار','saveDecision()','ghost',!!job)}</div></form></section>`;}
function formInputs(c){return `<details class="card" ${c.sources.length?'':'open'}><summary>روابط ومعلومات العميل</summary><form onsubmit="event.preventDefault();saveInputs()"><div class="grid2"><div><label for="clientName">اسم العميل</label><input id="clientName" value="${E(c.name)}"></div><div><label for="specialty">التخصص أو النشاط، لو معروف</label><input id="specialty" value="${E(c.specialty)}"></div></div><label for="links">روابط العميل — كل رابط في سطر</label><textarea id="links" rows="3">${E(c.links)}</textarea><label for="notes">رسائل أو معلومات قالها العميل</label><textarea id="notes" rows="3">${E(c.notes)}</textarea>${btn('حفظ المدخلات','saveInputs()','',!!job)}</form></details>`;}
function materialForm(){return `<details class="card"><summary>إضافة محتوى متعذر قراءته أو صور للمنصة</summary><p class="muted">المادة تتسجل على إنها من الفريق، وتعدّي على مراجعة الأدلة. لإضافة منشورات، ضيف رابط المنشور وتاريخه والنص الظاهر.</p><label for="materialURL">رابط المصدر، إن وجد</label><input id="materialURL" type="url"><label for="materialText">النص المتاح</label><textarea id="materialText" rows="3"></textarea><div class="actions">${btn('حفظ النص','addMaterial()','',!!job)}<label class="upload">ارفع صورًا<input type="file" id="screenshots" accept="image/*" multiple onchange="addImages(this.files)"></label></div></details>`;}
function contentHTML(c){const sm=sample(c),pending=c.posts.filter(p=>p.status==='pending');return `<div class="actions">${btn('حلّل آخر عينة معتمدة','contentReview()','',!!job)}</div>${pending.length?`<details class="card" open><summary>${pending.length} منشور يحتاج اعتماد التاريخ والتصنيف</summary>${pending.map(p=>`<div class="post"><a href="${E(p.url)}" target="_blank" rel="noopener noreferrer">${E(p.date)} · افتح المنشور ↗</a><p>${E(p.text)}</p><div class="grid2"><label>نوع المحتوى<select onchange="editPost('${p.id}','category',this.value)">${CATEGORIES.map(x=>`<option ${x===p.category?'selected':''}>${x}</option>`).join('')}</select></label><label>الفورمات<select onchange="editPost('${p.id}','format',this.value)">${FORMATS.map(x=>`<option ${x===p.format?'selected':''}>${x}</option>`).join('')}</select></label></div>${evidenceHTML(p.evidence,c)}<div class="actions">${btn('اعتمد المنشور',`review('posts','${p.id}','approved')`)}${btn('استبعد',`review('posts','${p.id}','rejected')`,'ghost')}</div></div>`).join('')}</details>`:''}${sm.map(s=>`<section class="card"><div class="row"><h2>${E(s.name)}</h2><span class="tag blue">${s.total} منشورًا في العينة</span></div><p>من ${E(s.from)} إلى ${E(s.to)} · آخر منشور مقروء من ${s.daysSince} يومًا</p><p class="muted">آخر عينة متاحة، مش آخر 90 يوم. القراءة قد لا تشمل كل المنشورات؛ التاريخ هنا للعينة وليس إثباتًا لآخر نشاط على الحساب كله.</p>${s.mix.map(m=>`<div class="mix"><div class="row"><b>${E(m.category)}</b><span>${m.n} من ${s.total} · ${m.pct}%</span></div><div class="bar"><i style="width:${m.pct}%"></i></div></div>`).join('')}<details><summary>الفورمات والمنشورات المعتمدة</summary><p>${s.formats.map(x=>E(x.format)+': '+x.n).join('، ')}</p>${s.posts.map(p=>`<p><a href="${E(p.url)}" target="_blank" rel="noopener noreferrer">${E(p.date)} — ${E(p.category)}</a></p>`).join('')}</details></section>`).join('')||empty('مفيش منشورات مؤرخة ومعتمدة لحد دلوقتي. مش هنخترع نسب أو نحكم إن الصفحة فاضية.')} ${c.contentReview?`<section class="card"><h2>هل المحتوى بيظهر قوة العميل؟</h2><p>${E(c.contentReview.summary)}</p>${['strengths','gaps','recommendations'].map((k,i)=>`<h3>${['اللي شغال','اللي محتاج تحسين','اقتراحي'][i]}</h3>${A(c.contentReview[k]).map(x=>`<p>${E(x.text)} ${x.why?'— '+E(x.why):''}</p>${A(x.postIds).map(id=>{const p=c.posts.find(p=>p.id===id);return p?`<a href="${E(p.url)}" target="_blank" rel="noopener noreferrer">دليل من العينة ↗</a>`:'';}).join(' ')}`).join('')}`).join('')}<ul>${A(c.contentReview.missing).map(x=>`<li>${E(x)}</li>`).join('')}</ul></section>`:''}`;}
function questionsHTML(c){const m=missing(c);const batch=m.questions.slice(0,3);const knowns=QUESTIONS.map(([field])=>({field,...known(c,field)})).filter(x=>x.value);return `<section class="card"><h2>${m.questions.length?'الأسئلة اللي هتغيّر قرار فعلًا':'مفيش أسئلة أساسية ناقصة'}</h2><p class="muted">${m.questions.length} سؤالًا ناقصًا. بنعرض 3 في المرة؛ الإجابات السابقة والمعلومات المعتمدة مش هتتكرر.</p>${m.pending.length?`<div class="notice">${m.pending.map(q=>E(FIELDS[q.field])).join('، ')}: موجودة كمعلومات تحتاج اعتماد. راجعها في فحص المنصات بدل إعادة السؤال.</div>`:''}<form onsubmit="event.preventDefault();saveAnswers()">${batch.map(q=>`<label for="answer_${q.field}">${E(q.text)}</label><small>${E(q.why)}</small><textarea id="answer_${q.field}" data-question="${q.field}" rows="2"></textarea>`).join('')}${batch.length?btn('حفظ الإجابات وعرض الناقص التالي','saveAnswers()'):''}</form></section><details class="card"><summary>المعلومات اللي مش هنرجع نسألها</summary>${knowns.map(x=>`<div class="fact"><div><b>${E(FIELDS[x.field])}</b><p>${E(x.value)}</p><small>${E(x.origin)}</small>${evidenceHTML(x.evidence,c)}</div>${btn('تعديل الإجابة',`editAnswer('${x.field}')`,'ghost')}</div>`).join('')||'<p>المعلومات المعتمدة هتظهر هنا.</p>'}</details>`;}
function ready(c,n){if(n===0)return !!c.presenceAt||c.sources.some(s=>['read','partial'].includes(s.status));if(n===1)return !!c.examinedAt||c.facts.length>0||c.findings.length>0;if(n===2)return !!c.conflictsReviewedAt;if(n===3)return !!c.contentReview;if(n===4)return !!c.priorities;return true;}
function can(c,n){return n===0||c.completed.slice(0,n).filter(Boolean).length===n;}
function openStep(n){const c=get();if(!c||job)return;if(!can(c,n))return notify('راجع واعتمد الخطوة اللي قبلها الأول.');step=n;if(n===2)computeConflicts(c);render();window.scrollTo(0,0);}
function next(){const c=get();if(!ready(c,step))return notify('كمّل الفحص أو سجّل تعذر التحقق قبل الانتقال.');if(step===1&&c.facts.some(f=>f.status==='pending'))return notify('اعتمد أو استبعد المعلومات المقترحة الأول.');if(step===2&&c.conflicts.some(x=>x.status==='open'))return notify('احسم الاختلافات أو سجّل إنها تحتاج سؤال العميل.');c.completed[step]=true;touch(c);if(step<5){step++;if(step===2)computeConflicts(c);}render();window.scrollTo(0,0);}
function render(){if(!bootReady){document.getElementById('app').innerHTML=empty('تحميل ملف العملاء…');return;}const c=get();document.getElementById('app').innerHTML=`<div class="shell ${sidebar?'':'collapsed'}"><aside><button class="side-close ghost" onclick="toggleSide()" aria-label="إغلاق القائمة">×</button><div class="brand"><span>TT</span><b>Techno Team</b></div><p class="muted">البحث المبدئي · V${VERSION}</p><button class="ghost full" onclick="home()">كل العملاء</button>${c?`<div class="client-name"><b>${E(c.name)}</b><small>${E(c.specialty||'ملف العميل')}</small></div><nav>${STEPS.map((s,i)=>`<button class="nav ${i===step?'active':''}" onclick="openStep(${i})" ${can(c,i)?'':'disabled'}><span>${c.completed[i]?'✓':i+1}</span>${s}</button>`).join('')}</nav>`:''}<div class="side-bottom">${btn('إعداد الاتصال','settings()','ghost full',!!job)}${btn('نسخة بيانات','exportData()','ghost full')}<label class="upload">استيراد ملف<input id="import" type="file" accept=".json,.html" onchange="importData(this.files[0])"></label><small>الحفظ على هذا المتصفح</small></div></aside><main><header><div class="row"><button class="ghost" onclick="toggleSide()" aria-label="فتح أو إغلاق القائمة">☰</button><span>${c?E(c.name):'مساحة العملاء'}</span></div><span class="muted">${saveError?'الحفظ يحتاج انتباه':'محفوظ على الجهاز'} · V${VERSION}</span></header>${saveError?`<div class="notice red">${E(saveError)} ${btn('نزّل نسخة','exportData()','ghost')}</div>`:''}${c?clientView(c):homeView()}<footer>Techno Team · بحث مبدئي موثق · كل قرار محفوظ مع العميل</footer></main></div>`;renderProgress();}
function homeView(){return `<section class="hero"><span class="eyebrow">نفهم العميل الأول</span><h1>من الرابط، لفهم واضح<br>ومناقشة مفيدة.</h1><p>نكتشف حضوره، نفحص المنصات، ونراجع المحتوى. بعدها نسألك عن الناقص بس.</p>${btn('+ إضافة عميل','newClient()')}</section><div class="row section-head"><h2>ملفات العملاء</h2><span>${DB.clients.length} ملف</span></div><div class="grid3">${DB.clients.map(c=>`<article class="card"><span class="tag blue">${STEPS[c.completed.filter(Boolean).length>5?5:c.completed.filter(Boolean).length]}</span><h2>${E(c.name)}</h2><p>${E(c.specialty||'التخصص لم يحدد')}</p><small>${c.sources.filter(s=>['read','partial'].includes(s.status)).length} مصدر مقروء · ${c.facts.filter(f=>f.status==='approved').length} معلومة معتمدة</small>${btn('افتح الملف',`openClient('${c.id}')`,'full')}</article>`).join('')||empty('ضيف اسم العميل ورابطه، والباقي هنكتشفه خطوة خطوة.')}</div>`;}
function clientView(c){let body='';if(step===0)body=`${formInputs(c)}<div class="actions">${btn(c.presenceAt?'استكمل البحث وأعد المتعذر':'ابدأ اكتشاف الحضور','discover()','',!!job)}</div><div class="grid2">${sourceCards(c)}</div>${materialForm()}`;if(step===1)body=`<div class="actions">${btn(c.examinedAt?'استكمل الفحص الناقص':'افحص المصادر المقروءة','examine()','',!!job)}</div>${factsHTML(c)}<div class="grid2">${findingCards(c)||empty('نقاط القوة والملاحظات هتظهر بالدليل بعد الفحص.')}</div>`;if(step===2)body=`<div class="card"><h2>نفس المعلومات على كل المنصات؟</h2><p>الاختلاف مش دائمًا خطأ؛ ممكن يكون فرع أو خدمة أو تحديث مختلف.</p>${btn('حدّث المقارنة','refreshConflicts()','ghost')}</div>${c.conflicts.map(x=>`<article class="card"><span class="tag amber">${x.status==='open'?'اختلاف يحتاج حسم':x.status==='ask'?'سؤال محدد للعميل':'تم تفسيره'}</span><h3>${E(x.title)}</h3><p>${E(x.reason)}</p>${x.items.map(f=>`<p><b>${E(c.sources.find(s=>s.id===f.sourceId)?.platform)}</b>: ${E(f.value)}</p>${evidenceHTML(f.evidence,c)}`).join('')}<label>تفسير الاختلاف أو السؤال المحدد</label><textarea id="conflict_${x.id}" rows="2">${E(x.resolution)}</textarea><div class="actions">${btn('حسمت السياق',`resolveConflict('${x.id}','resolved')`)}${btn('محتاج سؤال العميل',`resolveConflict('${x.id}','ask')`,'ghost')}</div></article>`).join('')||empty('مفيش اختلافات مكتشفة بين المعلومات المعتمدة؛ ده مقيد بالمصادر اللي اتقرت.')}${btn('أنهيت مراجعة المقارنة','finishConflicts()','',!!job)}`;if(step===3)body=contentHTML(c)+materialForm();if(step===4)body=`<div class="actions">${btn('رتّب أهم فرص التحسين','priorities()','',!!job)}</div>${c.priorities?`<section class="card"><h2>اقتراحنا لبدء التحسين</h2><p>${E(c.priorities.summary)}</p></section>${A(c.priorities.items).map((x,i)=>`<article class="card"><span class="tag blue">أولوية ${i+1} · ${x.status==='approved'?'قرار معتمد':'مقترح للنقاش'}</span><h3>${E(x.title)}</h3><p>${E(x.action)}</p><div class="insight"><b>ليه؟</b><p>${E(x.why)}</p><b>محتاجين نحسم</b><p>${E(x.decisionQuestion)}</p></div>${A(x.findingIds).map(id=>evidenceHTML(c.findings.find(f=>f.id===id)?.evidence,c)).join('')}${btn('اعتمد الاتجاه',`approvePriority('${x.id}')`,'ghost')}</article>`).join('')||empty('مفيش ملاحظات معتمدة كفاية لاقتراح أولويات بالدليل.')}`:empty('اعتمد الملاحظات اللي شايفها صحيحة؛ الأولويات هتتبني عليها.')}`;if(step===5)body=questionsHTML(c)+`<section class="card"><h2>ملخص البحث</h2><p>المعلومات والأدلة والقرارات محفوظة. المراحل اللاحقة هنضيفها بعد ما نختبر الجزء ده.</p>${btn('تحميل تقرير البحث','exportReport()','ghost')}</section>`;return `<div class="step-head"><span class="eyebrow">خطوة ${step+1} من ${STEPS.length} · البحث المبدئي فقط</span><h1>${STEPS[step]}</h1><p>${['نبدأ بالروابط الرسمية، ونبحث عن الموقع والسوشيال والحجز.','نقاط القوة والمشاكل، كل واحدة معاها الدليل واقتراح عملي.','نحسم الاختلافات بدل ما نختار معلومة بصمت.','آخر فترة نشاط مقروءة، ونسب محسوبة من العينة المعتمدة.','مختصر مفيد: إيه يستحق نشتغل عليه، وليه؟','كل سؤال هنا يكمّل معلومة ناقصة ويخدم قرار.'][step]}</p></div>${c.importNotice?`<details class="notice"><summary>بيانات الإصدار السابق محفوظة</summary>${E(c.importNotice)}</details>`:''}<div id="progress" class="progress" ${job?'':'hidden'}></div>${body}${discussion(c)}${c.limits.length?`<details class="card"><summary>حدود البيانات والتحليل · ${c.limits.length}</summary><ul>${c.limits.map(x=>`<li>${E(x)}</li>`).join('')}</ul></details>`:''}<div class="flow-footer"><div><b>${step===5?'الجزء الأول فقط':'نراجع، ثم نكمل'}</b><small>تقدر تناقش النتيجة قبل اعتماد الخطوة.</small></div><div class="actions">${step?btn('السابق',`openStep(${step-1})`,'ghost',!!job):''}${step<5?btn('اعتماد ومتابعة ←','next()','',!!job):''}</div></div>`;}
function home(){if(job)return notify('أوقف الخطوة الجارية الأول.');active='';render();}
function openClient(id){if(job)return;active=id;step=Math.min(5,get().completed.findIndex(x=>!x)<0?get().completed.filter(Boolean).length:get().completed.findIndex(x=>!x));if(step<0)step=0;render();}
function toggleSide(){sidebar=!sidebar;document.querySelector('.shell')?.classList.toggle('collapsed',!sidebar);}
function modal(html){const el=document.getElementById('modal');el.innerHTML=`<div class="modal-box"><button class="close ghost" onclick="closeModal()" aria-label="إغلاق">×</button>${html}</div>`;el.hidden=false;el.querySelector('input,textarea')?.focus();}
function closeModal(){document.getElementById('modal').hidden=true;}
function newClient(){modal(`<h2>نبدأ نفهم العميل</h2><form onsubmit="event.preventDefault();createClient()"><label for="newName">اسم العميل</label><input id="newName" required><label for="newSpecialty">التخصص، لو معروف</label><input id="newSpecialty"><label for="newLinks">رابط أو أكتر — كل رابط في سطر</label><textarea id="newLinks" rows="3"></textarea><label for="newNotes">معلومات أو رسائل من العميل، لو موجودة</label><textarea id="newNotes" rows="3"></textarea><button type="submit" class="full">إنشاء ملف العميل</button></form>`);}
function createClient(){const name=document.getElementById('newName')?.value.trim();if(!name)return;const exists=DB.clients.find(c=>norm(c.name)===norm(name));if(exists){closeModal();openClient(exists.id);return;}const c=prep({id:uid(),name,specialty:document.getElementById('newSpecialty').value.trim(),links:document.getElementById('newLinks').value.trim(),notes:document.getElementById('newNotes').value.trim(),created:Date.now()});DB.clients.push(c);active=c.id;step=0;syncNotes(c);touch(c);closeModal();render();}
function syncNotes(c){let s=c.sources.find(x=>x.kind==='client');if(c.notes.trim()){if(!s){s={id:uid(),kind:'client',platform:'معلومات العميل',identity:'confirmed',url:'',title:'رسائل ومعلومات قدمها العميل'};c.sources.push(s);}s.text=c.notes;s.status='read';}else if(s){c.sources=c.sources.filter(x=>x!==s);c.facts=c.facts.filter(f=>f.sourceId!==s.id);}}
function saveInputs(){const c=get(),name=document.getElementById('clientName').value.trim();if(!name){notify('اسم العميل مطلوب.');return false;}const links=document.getElementById('links').value.trim(),notes=document.getElementById('notes').value.trim(),specialty=document.getElementById('specialty').value.trim();const lines=links.split('\n').filter(x=>x.trim());if(lines.some(x=>!publicURL(x))){notify('فيه رابط غير صالح. استخدم رابط الصفحة المباشر بدل رابط المشاركة أو الدخول.');return false;}if(c.links!==links||c.notes!==notes||c.specialty!==specialty)invalidate(c);if(c.notes!==notes){const ids=c.sources.filter(x=>x.kind==='client').map(x=>x.id);c.facts=c.facts.filter(f=>!ids.includes(f.sourceId));c.findings=c.findings.filter(f=>!ids.includes(f.sourceId));}Object.assign(c,{name,links,notes,specialty});syncNotes(c);touch(c);notify('اتحفظت المدخلات.');return true;}
function identity(id,status){const c=get(),s=c.sources.find(x=>x.id===id);s.identity=status;invalidate(c);render();}
async function retrySource(id){await withJob('إعادة قراءة المصدر',async(c,signal,status)=>{status('محاولة جديدة…');await readSource(c,c.sources.find(x=>x.id===id),signal);invalidate(c);});}
function review(kind,id,status){const c=get(),x=c[kind].find(x=>x.id===id);if(!x)return;x.status=status;if(kind==='facts'){c.completed=c.completed.slice(0,2);c.conflictsReviewedAt=null;}if(kind==='posts'){c.contentReview=null;c.completed=c.completed.slice(0,3);}c.priorities=null;c.completed=c.completed.slice(0,4);touch(c);render();}
function editPost(id,key,value){const c=get(),p=c.posts.find(x=>x.id===id);p[key]=value;touch(c);}
function refreshConflicts(){computeConflicts(get());render();}
function resolveConflict(id,status){const c=get(),x=c.conflicts.find(x=>x.id===id),v=document.getElementById('conflict_'+id).value.trim();if(!v)return notify('اكتب تفسيرًا أو السؤال المحدد الأول.');x.status=status;x.resolution=v;touch(c);render();}
function finishConflicts(){const c=get();if(c.conflicts.some(x=>x.status==='open'))return notify('احسم الاختلافات أو سجّل السؤال المطلوب.');c.conflictsReviewedAt=Date.now();touch(c);notify('اتحفظت مراجعة الاختلافات.');}
function approvePriority(id){const c=get(),x=c.priorities.items.find(x=>x.id===id);if(x.status==='approved')return;x.status='approved';c.decisions.push({id:uid(),step:4,text:x.title+' — '+x.action,at:Date.now(),findingIds:x.findingIds});touch(c);render();}
function saveAnswers(){const c=get();document.querySelectorAll('[data-question]').forEach(el=>{const v=el.value.trim();if(v){const key=el.dataset.question;if(key.startsWith('conflict_')){const x=c.conflicts.find(x=>x.id===key.slice(9));if(x){x.status='resolved';x.resolution=v;}}else c.answers[key]=v;}});c.priorities=null;c.completed=c.completed.slice(0,4);touch(c);render();}
function editAnswer(field){const c=get();modal(`<h2>تعديل ${E(FIELDS[field])}</h2><textarea id="editValue" rows="4">${E(known(c,field)?.value)}</textarea>${btn('حفظ التعديل',`setAnswer('${field}')`)}`);}
function setAnswer(field){const c=get(),v=document.getElementById('editValue').value.trim();if(!v)return notify('اكتب الإجابة؛ حذفها يحتاج مراجعة المعلومات المعتمدة.');c.answers[field]=v;touch(c);closeModal();render();}
function addMaterial(){const c=get(),text=document.getElementById('materialText').value.trim(),raw=document.getElementById('materialURL').value.trim(),url=raw?publicURL(raw):'';if(!text)return notify('ضيف النص المتاح الأول.');if(raw&&!url)return notify('رابط المصدر غير صالح.');c.sources.push({id:uid(),url,kind:'manual',platform:url?platform(url):'مواد الفريق',identity:'confirmed',status:'read',text,title:'نص أضافه الفريق',links:extractLinks(text,url),note:'محتوى أضافه الفريق؛ لم يُقرأ الرابط بشكل مستقل.'});invalidate(c);render();notify('اتحفظ النص؛ افحصه من خطوة فحص المنصات.');}
async function addImages(files){const selected=[...files].slice(0,8);if(!selected.length)return;await withJob('قراءة صور المنصة',async(c,signal,status)=>{for(let i=0;i<selected.length;i++){const f=selected[i];if(f.size>10*1024*1024){limit(c,'الصورة أكبر من 10 MB: '+f.name);continue;}status('قراءة الصورة '+(i+1)+' من '+selected.length);const img=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});try{const r=await ai('انسخ النص الظاهر في الصورة فقط بما فيه الاسم والتخصص والمنشور والتاريخ والتعليقات. لا تخمن غير المقروء ولا تخترع URL أو أرقام. JSON {"text":"","limits":[]}.',{signal,image:img,max:3500});if(T(r.text).length<20){limit(c,'الصورة غير مقروءة: '+f.name);continue;}c.sources.push({id:uid(),url:'',kind:'manual',platform:'صورة من الفريق',identity:'confirmed',status:'partial',text:r.text,title:f.name,links:[],note:'نص مستخرج من صورة؛ راجع الهوية والتاريخ. الصورة ليست إثباتًا لقراءة المنصة كاملة.'});A(r.limits).forEach(x=>limit(c,f.name+': '+T(x)));touch(c);}catch(e){if(signal.aborted)throw e;limit(c,'تعذرت قراءة صورة '+f.name+': '+e.message);}}invalidate(c);});}
async function askDiscussion(){const c=get(),q=document.getElementById('discuss').value.trim();if(!q)return;if(job)return;const n=step;(c.discussions[n]||=[]).push({role:'user',text:q,at:Date.now()});touch(c);await withJob('مناقشة '+STEPS[n],async(c,signal,status)=>{status('مراجعة الأدلة والاقتراح…');const r=await ai(`ناقش المستخدم كزميل مستشار في خطوة ${STEPS[n]}. أجب عن سؤاله باختصار: نتيجة أو توصية واضحة وسببها؛ سؤال واحد لو محتاج قرارًا. لا تعتبر كلامك قرارًا معتمدًا، ولا تحفظ معلومة كحقيقة من المحادثة. لو سأل عن شيء خارج البيانات قل تعذر التحقق وحدد المطلوب. JSON {"reply":"","evidence":[{"sourceId":"","quote":""}]}. سجل البحث ${JSON.stringify(researchContext(c))}. المصادر ${JSON.stringify(c.sources.filter(s=>s.identity==='confirmed').map(s=>({id:s.id,url:s.url,text:T(s.text).slice(0,2500)})))}. آخر المناقشة ${JSON.stringify(c.discussions[n].slice(-6))}`,{signal,max:1800});c.discussions[n].push({role:'assistant',text:T(r.reply),evidence:validEvidence(r.evidence,c),at:Date.now()});});setTimeout(()=>document.getElementById('chatlog')?.scrollTo({top:999999}),0);}
function saveDecision(){const c=get(),q=document.getElementById('discuss').value.trim();if(!q)return notify('اكتب القرار اللي عايز تحفظه في خانة رأيك.');c.decisions.push({id:uid(),step,text:q,at:Date.now()});(c.discussions[step]||=[]).push({role:'user',text:'قرار اعتمدته: '+q,at:Date.now()});touch(c);render();}
function settings(){let endpoint='';try{endpoint=localStorage.getItem('blueprint_ai_endpoint')||'https://blueprint-ai-server.vercel.app/api/ai';}catch{}modal(`<h2>إعداد الاتصال</h2><p class="muted">الموديل والمفتاح بيحددهم السيرفر. مش محتاج مفتاح OpenAI إضافي هنا.</p><label for="endpoint">رابط السيرفر</label><input id="endpoint" type="url" value="${E(endpoint)}"><label for="token">توكن اتصال السيرفر إن كان محميًا</label><input id="token" type="password" autocomplete="off"><small>توكن السيرفر فقط، مش مفتاح OpenAI؛ يُحفظ للجلسة ولا يدخل النسخ الاحتياطية.</small>${btn('حفظ الاتصال','saveSettings()')}${btn('اختبار الاتصال','testConnection()','ghost')}<p id="connectionResult"></p>`);}
function saveSettings(){const endpoint=document.getElementById('endpoint').value.trim();try{const u=new URL(endpoint);if(u.protocol!=='https:'||!u.pathname.endsWith('/api/ai'))throw Error();localStorage.setItem('blueprint_ai_endpoint',endpoint);sessionStorage.setItem('tt_server_token',document.getElementById('token').value.trim());notify('اتحفظ الاتصال.');}catch{notify('استخدم رابط https بينتهي بـ /api/ai.');}}
async function testConnection(){saveSettings();const el=document.getElementById('connectionResult');el.textContent='اختبار الاتصال…';try{await ai('JSON {"ok":true} فقط',{max:50});el.textContent='الاتصال شغال ✓';}catch(e){el.textContent=e.message;}}
function download(name,body,type='application/json'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([body],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function exportData(){download('Techno_Team_Research_V3_34_Backup.json',JSON.stringify({format:'tt-research',version:VERSION,at:Date.now(),db:DB},null,2));}
async function importData(file){if(!file)return;if(job)return notify('أوقف الخطوة الجارية قبل الاستيراد.');try{const raw=await file.text();let data;if(file.name.endsWith('.html')){const doc=new DOMParser().parseFromString(raw,'text/html'),el=doc.getElementById('tt-client-backup')||doc.getElementById('tt-research-backup');if(!el)throw Error('ملف HTML مش نسخة بيانات قابلة للاسترجاع.');data=json(el.textContent);}else data=json(raw);const db=data.db||data;let clients=A(db.clients);if(!clients.length&&data.client)clients=[data.client];if(!clients.length)throw Error('الملف مفيهوش عملاء؛ بياناتك الحالية لم تتغير.');if(data.format==='tt-research'||db.version===VERSION)clients=clients.map(prep);else clients=clients.map(legacyClient);const existing=new Set(DB.clients.map(x=>x.id));let added=0;for(const c of clients){if(existing.has(c.id)){c.id=uid();c.name+=' — نسخة مستوردة';}DB.clients.push(c);existing.add(c.id);added++;}touch(DB.clients.at(-1));render();notify('اتضاف '+added+' ملف؛ الملفات الحالية محفوظة.');}catch(e){notify('تعذر الاستيراد: '+e.message);}}
function exportReport(){const c=get();if(!c)return;const report=`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>بحث ${E(c.name)}</title><style>body{font:16px/1.9 Tahoma,sans-serif;margin:30px;color:#173459}section{border:1px solid #dce7f5;padding:20px;border-radius:14px;margin:20px 0}a{overflow-wrap:anywhere}button,input,textarea,.actions{display:none}blockquote{background:#f4f7fe;padding:15px}.bar{height:8px;background:#edf2ff}.bar i{display:block;height:8px;background:#1469ff}pre{white-space:pre-wrap}</style><h1>${E(c.name)} — البحث المبدئي</h1><p>${new Date().toLocaleDateString('ar-EG')} · V${VERSION}</p><section><h2>الحضور الرقمي</h2>${sourceCards(c)}</section><section><h2>المعلومات ونقاط القوة</h2>${factsHTML(c)}${findingCards(c)}</section><section><h2>المحتوى</h2>${contentHTML(c)}</section><section><h2>القرارات</h2>${c.decisions.map(x=>`<p>${E(x.text)}</p>`).join('')}</section><section><h2>الناقص وحدود الدراسة</h2>${missing(c).questions.map(q=>`<p>${E(q.text)}</p>`).join('')}<ul>${c.limits.map(x=>`<li>${E(x)}</li>`).join('')}</ul></section><script id="tt-research-backup" type="application/json">${JSON.stringify({format:'tt-research',version:VERSION,db:{version:VERSION,clients:[c]}}).replace(/</g,'\\u003c')}<\/script></html>`;download('Techno_Team_Research_Report.html',report,'text/html');}
window.addEventListener('resize',()=>{if(innerWidth<=720&&sidebar){sidebar=false;document.querySelector('.shell')?.classList.add('collapsed');}});
window.addEventListener('beforeunload',e=>{if(job||saveError){e.preventDefault();e.returnValue='';}});
boot();
